create or replace function public.layer2_run_batch_dispatch(p_batch_id uuid) returns bigint language plpgsql security definer set search_path=pg_catalog,public,vault,net as $$ declare v_key text; v_req bigint; begin if current_user not in ('service_role','postgres') then raise exception 'service_role required' using errcode='42501'; end if; select decrypted_secret into v_key from vault.decrypted_secrets where name='coursefinder_pilot_automation_key' limit 1; if v_key is null then raise exception 'pilot automation key unavailable'; end if; select net.http_post(url:='https://fxcwkweaxjtknorudmwp.supabase.co/functions/v1/layer2-batch-runner',headers:=jsonb_build_object('content-type','application/json','x-cf-pilot-key',v_key),body:=jsonb_build_object('batch_id',p_batch_id),timeout_milliseconds:=120000) into v_req; return v_req; end $$; revoke all on function public.layer2_run_batch_dispatch(uuid) from public,anon,authenticated; grant execute on function public.layer2_run_batch_dispatch(uuid) to service_role;
